// UNWRAP
const input = ($input.first().json.body) ? $input.first().json.body : $input.first().json;

// VALIDATE
const amount = parseFloat(input.amount);
if (isNaN(amount) || amount <= 0) throw new Error('Payment amount must be positive');
if (amount > 100000) throw new Error('Amount exceeds maximum');
if (!input.booking_id)  throw new Error('Missing booking_id');
if (!input.customer_id) throw new Error('Missing customer_id');

// DETERMINE TYPE — preserve 'deposit' if caller sends it, otherwise 'balance'
const sentType = (input.payment_type || '').toLowerCase();
const payment_type = (sentType === 'deposit') ? 'deposit' : 'balance';

// is_partial: only relevant for balance payments
const balance = parseFloat(input.balance_due || 999999);
const is_partial = payment_type === 'balance' && amount < (balance - 0.005);

// GENERATE REFERENCE NUMBER
const ts = new Date();
const pad = n => String(n).padStart(2,'0');
const stamp = ts.getFullYear() + pad(ts.getMonth()+1) + pad(ts.getDate()) +
              pad(ts.getHours()) + pad(ts.getMinutes()) + pad(ts.getSeconds());
const rand = Math.random().toString(36).slice(2,6).toUpperCase();
const prefix = payment_type === 'deposit' ? 'DEP' : 'REF';
const reference_number = prefix + '-' + stamp + '-' + rand;

return {
  json: {
    ...input,
    tenant_id: parseInt(input.tenant_id || $input.first().json.headers?.['x-tenant-id'] || $input.first().json.query?.tenant_id || '0'),
    amount,
    payment_type,
    is_partial,
    reference_number,
    payment_method:    input.payment_method || 'cash',
    deposit_reference: input.deposit_reference || null,
    // Explicit trim prevents whitespace-corrupted JWTs reaching the auth header
    jwt: String(input.jwt || '').trim()
  }
};

const sanitize   = $('Code: Sanitize').first().json;
const paymentNode = $('DB: Record Payment').first().json;

// paymentData: use API response when successful; fall back to {} so we never
// crash if DB: Record Payment itself failed (network error, 5xx etc.)
const paymentData = paymentNode?.success ? (paymentNode.data ?? paymentNode) : {};
// detailsRaw: DB: Get Customer Details enrichment (best-effort, may 401)
const detailsRaw  = ($json.success !== false) ? ($json.data ?? $json) : {};
// webhookData: original sanitised webhook body as the final safety net
const webhookData = sanitize;

// Merge order: webhookData (base) → paymentData (richer) → detailsRaw (freshest)
const raw = { ...webhookData, ...paymentData, ...detailsRaw };

const customer = {
  ...raw,
  email:      raw.customer_email || raw.email      || sanitize.email      || '',
  full_name:  raw.customer_name  || raw.full_name  || 'Valued Customer',
  event_date: raw.event_date     || raw.date_from  || raw.booking_date    || null,
};

const payment_type = sanitize.payment_type;
const is_partial   = sanitize.is_partial;
const amount       = parseFloat(sanitize.amount || 0);
const ref          = sanitize.reference_number || '\u2014';
const remaining    = parseFloat(raw.balance_due ?? raw.new_balance ?? 0);
const total        = parseFloat(customer.total_amount || 0);

const fmt = n => '\u00a3' + parseFloat(n || 0).toFixed(2);
const fmtDate = d => {
  if (!d) return '\u2014';
  const dt = new Date(String(d).slice(0,10) + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
};
const fmtTime = t => t ? String(t).slice(0,5) : '\u2014';

let subject, headingColour, headingText, statusBadge, bodyText;

if (payment_type === 'deposit') {
  subject       = `Deposit Payment Confirmed \u2014 ${fmtDate(customer.event_date)} | Ref: ${ref}`;
  headingColour = '#6366f1';
  headingText   = 'Deposit Payment Confirmed';
  statusBadge   = { text:'DEPOSIT RECEIVED', bg:'#eef2ff', color:'#4f46e5' };
  bodyText      = `Thank you for your deposit payment of <strong>${fmt(amount)}</strong>. Your booking for <strong>${customer.room_name || 'your venue'}</strong> is now secured.`;
} else if (is_partial) {
  subject       = `Payment Received \u2014 Remaining Balance: ${fmt(remaining)} | Ref: ${ref}`;
  headingColour = '#f59e0b';
  headingText   = 'Partial Balance Payment Received';
  statusBadge   = { text:'PAYMENT RECEIVED', bg:'#fffbeb', color:'#b45309' };
  bodyText      = `Thank you for your payment of <strong>${fmt(amount)}</strong>. Your remaining balance of <strong>${fmt(remaining)}</strong> is due before your event date.`;
} else {
  subject       = `Balance Fully Settled \u2014 Booking Confirmed \u2713 | Ref: ${ref}`;
  headingColour = '#10b981';
  headingText   = 'Balance Fully Settled \u2713';
  statusBadge   = { text:'FULLY PAID', bg:'#ecfdf5', color:'#065f46' };
  bodyText      = `Thank you for your final payment of <strong>${fmt(amount)}</strong>. Your booking balance is now <strong>fully settled</strong> \u2014 we look forward to hosting your event!`;
}

const remainingRow = remaining > 0
  ? `<tr style="border-top:1px solid #e2e8f0;"><td style="padding:8px 0 5px;color:#64748b;">Balance Remaining</td><td style="padding:8px 0 5px;color:#f59e0b;font-weight:700;text-align:right;">${fmt(remaining)}</td></tr>`
  : `<tr style="border-top:1px solid #e2e8f0;"><td style="padding:8px 0 5px;color:#64748b;">Balance Remaining</td><td style="padding:8px 0 5px;color:#10b981;font-weight:700;text-align:right;">\u00a30.00 \u2014 Fully Paid \u2713</td></tr>`;

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head>
<body style="margin:0;padding:0;background:#f8fafc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">
  <div style="max-width:600px;margin:0 auto;padding:32px 16px;">
    <div style="background:${headingColour};border-radius:12px 12px 0 0;padding:32px;text-align:center;">
      <p style="margin:0 0 6px;color:rgba(255,255,255,0.8);font-size:12px;letter-spacing:1.5px;text-transform:uppercase;">VenueDesk Booking System</p>
      <h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;line-height:1.3;">${headingText}</h1>
    </div>
    <div style="background:#ffffff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 12px 12px;padding:32px;">
      <div style="text-align:center;margin-bottom:24px;">
        <span style="display:inline-block;background:${statusBadge.bg};color:${statusBadge.color};font-size:11px;font-weight:700;letter-spacing:1.5px;padding:6px 18px;border-radius:20px;">${statusBadge.text}</span>
      </div>
      <p style="margin:0 0 16px;color:#1e293b;font-size:15px;">Dear <strong>${customer.full_name || 'Valued Customer'}</strong>,</p>
      <p style="margin:0 0 24px;color:#374151;font-size:15px;line-height:1.7;">${bodyText}</p>
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:20px;margin-bottom:16px;">
        <p style="margin:0 0 14px;color:#0f172a;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;">Booking Details</p>
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <tr><td style="padding:5px 0;color:#64748b;width:45%;">Room / Venue</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${customer.room_name || '\u2014'}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Event Date</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${fmtDate(customer.event_date)}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Time</td><td style="padding:5px 0;color:#1e293b;font-weight:600;">${fmtTime(customer.start_time)} \u2013 ${fmtTime(customer.end_time)}</td></tr>
        </table>
      </div>
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:20px;margin-bottom:24px;">
        <p style="margin:0 0 14px;color:#0f172a;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;">Payment Summary</p>
        <table style="width:100%;border-collapse:collapse;font-size:14px;">
          <tr><td style="padding:5px 0;color:#64748b;">Total Booking Value</td><td style="padding:5px 0;color:#1e293b;text-align:right;">${fmt(total)}</td></tr>
          <tr><td style="padding:5px 0;color:#64748b;">Amount Paid (This Transaction)</td><td style="padding:5px 0;color:${headingColour};font-weight:700;text-align:right;">${fmt(amount)}</td></tr>
          ${remainingRow}
        </table>
      </div>
      <div style="background:#eef2ff;border-radius:8px;padding:14px 20px;margin-bottom:28px;text-align:center;">
        <p style="margin:0;color:#64748b;font-size:12px;">Payment Reference</p>
        <p style="margin:4px 0 0;color:#4f46e5;font-size:17px;font-weight:700;letter-spacing:0.5px;">${ref}</p>
      </div>
      <p style="margin:0;color:#64748b;font-size:13px;line-height:1.6;">Please keep this email as your payment receipt. If you have any questions, reply quoting your reference number or contact us at <a href="mailto:bookings@venuedesk.co.uk" style="color:#6366f1;text-decoration:none;">bookings@venuedesk.co.uk</a>.</p>
    </div>
    <div style="text-align:center;padding:20px 0 0;">
      <p style="margin:0;color:#94a3b8;font-size:11px;">This is an automated message from VenueDesk Booking System. Please do not reply to this email directly.</p>
    </div>
  </div>
</body></html>`;

return { json: { ...customer, subject, html, email: customer.email } };
